import fitz, subprocess, pathlib, concurrent.futures, os, time
ROOT=pathlib.Path('/mnt/data/audit_work'); ROOT.mkdir(exist_ok=True)
PDFS={'ch':'/mnt/data/chattin with chatgpt.pdf','watch':'/mnt/data/chatgpt-watch-your-step(2).pdf'}
items=[(key,i,path) for key,path in PDFS.items() for i in range(len(fitz.open(path)))]

def do(item):
 key,i,path=item
 try:
  doc=fitz.open(path); p=doc[i]; native=p.get_text(); blocks=p.get_text('dict')['blocks']; images=[b for b in blocks if b['type']==1]
  if key=='ch' and len(native)>300 and i<4:
   res=native
  elif images:
   suffix=images[0].get('ext','png'); inp=ROOT /f'{key}_{i+1:03d}.{suffix}'
   inp.write_bytes(images[0]['image'])
   cp=subprocess.run(['tesseract',str(inp),'stdout','-l','eng','--psm','3'],stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=95)
   res=cp.stdout.decode('utf8','replace')
   inp.unlink(missing_ok=True)
  else:res=native
  out=ROOT/f'{key}_{i+1:03d}.txt'; out.write_text(res,encoding='utf8'); return key,i,len(res),''
 except Exception as e: return key,i,0,str(e)

if __name__=='__main__':
 print('START',len(items), flush=True)
 t=time.monotonic()
 with concurrent.futures.ThreadPoolExecutor(max_workers=7) as pool:
  for ix, (key,i,l,err) in enumerate(pool.map(do,items)):
   if ix%20==0 or err:print('DONE',ix+1,'/',len(items),key,i+1,l,err,'time',round(time.monotonic()-t),flush=True)
 for k,path in PDFS.items():
  p=ROOT/f'{k}_all.txt'
  n=len(fitz.open(path))
  p.write_text(''.join(f'\n### {k.upper()} PAGE {i+1}\n\n'+(ROOT/f'{k}_{i+1:03d}.txt').read_text('utf8') for i in range(n)),encoding='utf8')
  print('COMPLETE',k,'chars',p.stat().st_size, flush=True)
