(()=>{'use strict';const data=JSON.parse(document.getElementById('corpus').textContent);const byId=Object.fromEntries(data.sources.map(s=>[s.id,s]));const topics=Object.entries(data.themes).map(([id,t])=>({id,label:t.label,count:t.count})).sort((a,b)=>b.count-a.count);const all=[];for(const s of data.sources)for(const m of s.messages){m.source=s;all.push(m)};
